const b = $('Webhook').first().json.body || {};
if (b.secret !== 'furajul-05oct-Kc4tX9') throw new Error('bad secret');
return [{ json: { dry: b.dry !== false } }];

const t = $input.first().json; const msgs = t.messages || [];
if (!msgs.length) throw new Error('ABORT: thread not found');
const hd = m => { const o = {}; for (const x of ((m.payload||{}).headers||[])) o[x.name.toLowerCase()] = x.value; return o; };
const last = msgs[msgs.length-1]; const H = hd(last); const first = hd(msgs[0]);
if (!/rajul\.vohra@gmail\.com/i.test(first.to || '')) throw new Error('ABORT: original To is ' + first.to);
const others = msgs.filter(m => !/sidanaventures\.com/i.test(hd(m).from || ''));
if (others.length) throw new Error('ABORT: thread already has a reply from ' + hd(others[0]).from + ' - read it before following up');
const subj = /^re:/i.test(first.subject) ? first.subject : 'Re: ' + first.subject;
const html = '<div dir="ltr" style="font-family:Arial,Helvetica,sans-serif;font-size:small;color:#222222"><div>Dear Rajul,</div><div><br></div><div>Hope you are doing well. Following up on the two opportunities I shared last week, Washtro (hyperlocal garment care) and Chayan Karo (home-services marketplace).</div><div><br></div><div>If either looks interesting, I would be happy to set up a short call with the founders at a time that suits you. And if neither fits what you are looking for, just let me know the sectors or stages you prefer, and I will make sure the next deals I share are closer to your interests.</div><div><br></div><div>Looking forward to hearing from you.</div><div><br></div><div>Regards,</div><div><b>Chaman Yadav</b></div><div>Investor Relations</div><div>SIDANA VENTURES LLP</div><div>424A Tower B3, Spaze iTech Park, Sector 49, Sohna Road</div><div>Gurgaon, Haryana 122022</div><div>+91 87965 31802</div><div><a href="https://www.sidanaventures.com">www.sidanaventures.com</a></div></div>';
const refs = [H.references, H['message-id']].filter(Boolean).join(' ');
const mime = ['To: rajul.vohra@gmail.com', 'Subject: ' + subj, 'In-Reply-To: ' + H['message-id'], 'References: ' + refs, 'MIME-Version: 1.0', 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', Buffer.from(html, 'utf8').toString('base64')].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
return [{ json: { dry: $('Check').first().json.dry, threadId: t.id, messagesInThread: msgs.length, to: 'rajul.vohra@gmail.com', subject: subj, inReplyTo: H['message-id'], text: html.replace(/<div><br><\/div>/g,'\n').replace(/<[^>]+>/g,'\n').replace(/\n{2,}/g,'\n').trim(), body: { raw, threadId: t.id } } }];
